int videobuf_mmap(struct videobuf_queue *q, struct vm_area_struct *vma)
{
        struct videobuf_buffer *b;

        if (!(vma->vm_flags & VM_WRITE) || !(vma->vm_flags & VM_SHARED))
                return -EINVAL;

        list_for_each_entry(b, &q->maclist, q) {
                if ((unsigned long)vma->vm_start >= b->dma_addr &&
                    (unsigned long)vma->vm_end <= b->dma_addr + b->size) {
                        struct videobuf_mapping *map;

                        map = kzalloc(sizeof(*map), GFP_KERNEL);
                        if (!map)
                                return -ENOMEM;

                        map->vma = vma;
                        map->buf = b;
                        list_add(&map->list, &q->mappings);

                        vma->vm_ops = &videobuf_vm_ops;
                        vma->vm_private_data = map;

                        if (remap_pfn_range(vma,
                                            vma->vm_start,
                                            PFN_DOWN(b->dma_addr),
                                            vma->vm_end - vma->vm_start,
                                            vma->vm_page_prot)) {
                                vma->vm_ops = NULL;
                                vma->vm_private_data = NULL;
                                kfree(map);
                                return -EAGAIN;
                        }

                        videobuf_vm_open(vma);
                        return 0;
                }
        }

        return -EINVAL;
}

int videobuf_mmap(struct videobuf_queue *q, struct vm_area_struct *vma)
{
	int ret = -EINVAL;
	struct videobuf_buffer *buf = NULL;
	unsigned long offset = vma->vm_start - q->vb->baddr;

	if (vma->vm_flags & VM_WRITE && vma->vm_flags & VM_SHARED) {
		buf = videobuf_queue_find(q, offset);
		if (!buf)
			return -EINVAL;

		if (offset > buf->bsize)
			return -EINVAL;

		vma->vm_ops = &videobuf_vm_ops;
		vma->vm_private_data = buf;

		if (remap_pfn_range(vma, vma->vm_start, buf->dma_addr >> PAGE_SHIFT,
				    vma->vm_end - vma->vm_start, vma->vm_page_prot)) {
			vma->vm_flags &= ~VM_SHARED;
			vma->vm_flags |= VM_MAYSHARE;
			vma->vm_ops = NULL;
			vma->vm_private_data = NULL;
			return -ENOMEM;
		}

		vma->vm_flags |= VM_RESERVED;
		vma->vm_private_data = buf;
		return 0;
	}

	return ret;
}

int videobuf_mmap(struct videobuf_queue *q, struct vm_area_struct *vma)
{
	/* Check if the memory area is writable and shared */
	if (!(vma->vm_flags & VM_WRITE) || !(vma->vm_flags & VM_SHARED))
		return -EINVAL;

	/* Search for the first buffer in the queue that can be mapped */
	struct videobuf_buffer *b = NULL;
	for (int i = 0; i < q->num_buffers; ++i) {
		if (q->bufs[i] && q->bufs[i]->boff) {
			b = q->bufs[i];
			break;
		}
	}

	if (!b)
		return -EINVAL;

	/* Validate the buffer offset */
	if (vma->vm_start != b->boff)
		return -EINVAL;

	/* Allocate mapping structure */
	struct videobuf_mapping *map;
	map = kmalloc(sizeof(*map), GFP_KERNEL);
	if (!map)
		return -ENOMEM;

	/* Set up virtual memory area operations */
	vma->vm_ops = &videobuf_vm_ops;
	vma->vm_private_data = map;

	/* Remap virtual memory to physical memory */
	if (remap_pfn_range(vma, vma->vm_start, b->boff >> PAGE_SHIFT,
			    vma->vm_end - vma->vm_start,
			    vma->vm_page_prot)) {
		/* Store the virtual memory area for later use */
		map->vmas = vma;
	} else {
		vma->vm_flags |= VM_IO | VM_RESERVED;
	}

	/* Log the mapping details and open the virtual memory area */
	printk(KERN_INFO "Mapped buffer %p to address range 0x%lx-0x%lx\n",
	       b, vma->vm_start, vma->vm_end);

	return 0;
}

int videobuf_mmap(struct videobuf_queue *q, struct vm_area_struct *vma)
{
    struct videobuf_buffer *b = NULL;
    int ret;

    if (vma->vm_flags & (VM_WRITE | VM_SHARED)) {
        vma->vm_flags |= VM_MAYSHARE | VM_MAYREAD;
    } else {
        return -EINVAL;
    }

    vma->vm_ops = &videobuf_vm_ops;
    vma->vm_private_data = NULL;

    list_for_each_entry(b, &q->queued_list, q) {
        if (vma->vm_start >= b->boff) {
            if ((vma->vm_start - b->boff) + vma->vm_end <= b->size) {
                vma->vm_page_prot = pgprot_noncached(vma->vm_page_prot);
                ret = remap_pfn_range(vma, vma->vm_start, b->dma_addr >> PAGE_SHIFT,
                                      vma->vm_end - vma->vm_start, vma->vm_page_prot);
                if (!ret) {
                    vma->vm_private_data = b;
                    break;
                }
            }
        }
    }

    if (!vma->vm_private_data) {
        return -ENOMEM;
    }

    return 0;
}

int videobuf_mmap_setup(struct videobuf_queue *q, struct vm_area_struct *vma)
{
    struct videobuf_buffer *buf;

    if (!(vma->vm_flags & VM_WRITE) || !(vma->vm_flags & VM_SHARED))
        return -EINVAL;

    list_for_each_entry(buf, &q->stream, q) {
        if (buf->boff != vma->vm_start - q->offset)
            continue;

        if (!buf->boff || !buf->bsize)
            return -EINVAL;

        vma->vm_ops = &videobuf_vm_ops;
        vma->vm_private_data = buf;

        if (remap_pfn_range(vma, vma->vm_start, buf->phys_addr >> PAGE_SHIFT,
                            vma->vm_end - vma->vm_start, vma->vm_page_prot)) {
            vma->vm_flags |= VM_MIXEDMAP;
            return 0;
        }

        q->vmas = vma;
        return 0;
    }

    return -EINVAL;
}
